using System;

namespace Bodu.Extensions;

public partial class DateTimeExtensionsTests
{

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.LastDateOfWeekInMonth" />, when Called, returns the expected value.
    /// </summary>
    [TestMethod]
    [DynamicData(nameof(LastDateOfWeekInMonthTestData))]
    public void LastDateOfWeekInMonth_WhenCalled_ShouldReturnExpectedDate(DateTime input, DayOfWeek dayOfWeek, DateTime expected)
    {
        DateTime actual = input.LastDateOfWeekInMonth(dayOfWeek);

        Assert.AreEqual(expected, actual);
    }

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.LastDateOfWeekInMonth" />, when InvalidDayOfWeek, throws <see cref="ArgumentOutOfRangeException" />.
    /// </summary>
    [TestMethod]
    public void LastDateOfWeekInMonth_WhenInvalidDayOfWeek_ShouldThrowExactly()
    {
        DateTime input = new DateTime(2024, 4, 1);
        var invalidDay = (DayOfWeek)999;

        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() =>
        {
            _ = input.LastDateOfWeekInMonth(invalidDay);
        });
    }

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.LastDateOfWeekInMonth" />, when KindIsSet, returns the expected value.
    /// </summary>
    [TestMethod]
    [DataRow(DateTimeKind.Unspecified)]
    [DataRow(DateTimeKind.Utc)]
    [DataRow(DateTimeKind.Local)]
    public void LastDateOfWeekInMonth_WhenKindIsSet_ShouldPreserveKind(DateTimeKind kind)
    {
        DateTime input = new DateTime(2024, 7, 5, 10, 0, 0, kind);
        DateTime actual = input.LastDateOfWeekInMonth(DayOfWeek.Saturday);

        Assert.AreEqual(kind, actual.Kind);
    }

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.LastDateOfWeekInMonth" />, when MaxValue, returns <see langword="true" />.
    /// </summary>
    [TestMethod]
    public void LastDateOfWeekInMonth_WhenMaxValue_ShouldReturnValidResult()
    {
        DateTime actual = DateTime.MaxValue.LastDateOfWeekInMonth(DayOfWeek.Friday);

        Assert.IsTrue(actual <= DateTime.MaxValue);
    }

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.LastDateOfWeekInMonth" />, when MinValue, returns <see langword="true" />.
    /// </summary>
    [TestMethod]
    public void LastDateOfWeekInMonth_WhenMinValue_ShouldReturnValidResult()
    {
        DateTime actual = DateTime.MinValue.LastDateOfWeekInMonth(DayOfWeek.Monday);

        Assert.IsTrue(actual >= DateTime.MinValue && actual <= DateTime.MinValue.AddMonths(1).AddDays(-1));
    }

